_STK=re.compile(r'<table class="stk">(.*?)</table>',re.S)
def _stack(m):
    """Mobile card tables: label each <td> with its column header (data-label) so CSS can stack rows on narrow screens."""
    t=m.group(1);rows=re.findall(r'<tr\b[^>]*>(.*?)</tr>',t,re.S)
    if not rows or '<th' not in rows[0]:return m.group(0)
    hd=[html.escape(re.sub(r'<[^>]+>','',x).strip(),quote=True) for x in re.findall(r'<th[^>]*>(.*?)</th>',rows[0],re.S)]
    def row(r):
        i=iter(hd);return f'<tr{r.group(1)}>'+re.sub(r'<td(?=[ >])',lambda _:f'<td data-label="{next(i,"")}"',r.group(2))+'</tr>'
    body=re.sub(r'<tr\b([^>]*)>(.*?)</tr>',row,t[t.index('</tr>')+5:],flags=re.S)
    return '<table class="stk"><tr class="sh">'+rows[0]+'</tr>'+body+'</table>'
