_MON={m:i for i,m in enumerate(['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'],1)}
def NEXTD(dates,n=3):
    """Upcoming key dates (today or later, Europe/London) from a council's 'dates' list, soonest first.
    'D Mon YYYY: ...' -> that day; 'Mon YYYY: ...' -> end of month; 'YYYY: ...' -> only if a later year. Ranges/past dates are skipped."""
    import datetime as _d,calendar as _c
    try:
        from zoneinfo import ZoneInfo;today=_d.datetime.now(ZoneInfo('Europe/London')).date()
    except Exception:today=_d.date.today()
    out=[]
    for k in dates:
        h=k.split(':',1)[0].strip();m=re.fullmatch(r'(\d{1,2}) ([A-Z][a-z]{2}) (\d{4})',h);dt=None
        if m and m.group(2) in _MON:dt=_d.date(int(m.group(3)),_MON[m.group(2)],int(m.group(1)))
        else:
            m=re.fullmatch(r'([A-Z][a-z]{2}) (\d{4})',h)
            if m and m.group(1) in _MON:y,mo=int(m.group(2)),_MON[m.group(1)];dt=_d.date(y,mo,_c.monthrange(y,mo)[1])
            elif re.fullmatch(r'\d{4}',h) and int(h)>today.year:dt=_d.date(int(h),12,31)
        if dt and dt>=today:out.append((dt,k))
    return [k for _,k in sorted(out,key=lambda z:z[0])[:n]]
