# Newsletter landing page: a concrete reason to subscribe, built only from facts already sourced on the site:
# the 3 latest changes-log entries (first sentence + official source) and the next 3 deadlines from deadlines.py DL/AHEAD (read via ast).
def _nlpage():
    import ast,datetime as _d
    L=[]
    for nd in ast.parse(open('deadlines.py').read()).body:
        if isinstance(nd,ast.Assign) and getattr(nd.targets[0],'id','') in ('DL','AHEAD'):L+=ast.literal_eval(nd.value)
    keys=[_d.date.fromisoformat(r[0]).strftime('%-d %b %Y')+f': {i}' for i,r in enumerate(L)]
    dl=[(lambda a,n,c,t,u:f'<li><b>{_d.date.fromisoformat(a).strftime("%-d %b %Y")}, {e(n if c=="All of "+n else c)}:</b> {e(t)} (<a href="{e(u)}" rel="nofollow">source</a>)</li>')(*L[int(k.rsplit(": ",1)[1])]) for k in NEXTD(keys)]
    s1=lambda t:re.split(r'(?<=[a-z0-9)])\. (?=[A-Z])',t,maxsplit=1)[0].rstrip('.')+'.'
    rc=[c for c in _chs if not re.match(r'(Added|Re-checked|Now tracked)\b',c['text'])];pk=[]
    for c in rc:
        if len(pk)<3 and c['nation'] not in [p['nation'] for p in pk]:pk.append(c)
    pk+=[c for c in rc if c not in pk][:3-len(pk)];pk.sort(key=lambda c:c['date'],reverse=True)  # rule changes only (not site additions), one per nation where possible
    ch=''.join(f'<li><b>{_d.date.fromisoformat(c["date"]).strftime("%-d %b %Y")}, {e(c["nation"])}:</b> {e(s1(c["text"]))} (<a href="{e(c["source"])}" rel="nofollow">source</a>)</li>' for c in pk)
    nlf=FORMX.replace('<form class="signup"','<form class="signup" data-cta="newsletter-weekly" aria-label="Get the weekly what changed email"',1)
    return ('<p class="lead">One short email a week on UK short-term let and holiday let rules: what changed, what\'s coming, and the deadlines to act on. Every item links to its official source.</p>'
     +'<h2>What you get</h2><ul><li><b>What changed:</b> new licensing, planning, visitor levy, council tax and registration rules in England, Scotland, Wales and Northern Ireland.</li><li><b>What\'s coming:</b> consultations closing, council votes and levy start dates, before they happen.</li><li><b>Your council, if you want it:</b> pick your council below and we\'ll also email you when its rules change.</li></ul>'
     +PICK('newsletter-page')
     +'<h2>Recent changes we\'d have emailed you about</h2><ul class="anx">'+ch+'</ul><p><a href="changes.html">Full changes log</a></p>'
     +(('<h2>Deadlines coming up</h2><ul class="anx">'+''.join(dl)+'</ul><p><a href="deadlines.html">All upcoming deadlines</a></p>') if dl else '')
     +'<div class="nl" id="weekly-only"><h2>Just want the weekly email?</h2><p>No council needed. One short, sourced email a week.</p>'+nlf+'</div>'
     +'<p class="small">We store your email address (with our email provider, Resend) to send this newsletter, plus the council you chose if you signed up for alerts. Unsubscribe link in every email. No spam, no sharing. See our <a href="privacy.html">privacy page</a>.</p>')
page('newsletter.html','Weekly "what changed" newsletter',_nlpage(),desc='Free weekly email on UK short-term let and holiday let rules: what changed, what\'s coming and deadlines, each with an official source. Optional council alerts.',full_title='Free UK Short-Let Rules Newsletter: Weekly Changes and Deadlines')
page('privacy.html','Privacy and cookies','<p>This page explains what we collect when you use the UK Short-Let Rules Tracker. We keep it short.</p><h2>Analytics (Google Analytics 4)</h2><p>If you click <b>Accept</b> on the cookie bar, we use Google Analytics 4 to count page views and which tools are used (for example the checker, levy calculator and signup forms). This sets analytics cookies. We do not use advertising cookies, and ad features stay switched off. If you click <b>Reject</b>, or make no choice, no analytics cookies are set. You can change your mind any time with the <a href="#" class="ck-open">Cookie settings</a> link at the bottom of every page. Your choice is stored in your browser (local storage).</p><h2>Cloudflare Web Analytics</h2><p>We may also use Cloudflare Web Analytics, which is cookieless: it counts visits without cookies or tracking you across sites.</p><h2>Newsletter and alerts</h2><p>If you sign up for the newsletter or council alerts, we store your email address (and the council you chose, for alerts) with our email provider, Resend, only to send those emails. We also record which link brought you to sign up (for example a campaign tag in the link, or the website you came from), and which signup box on our site you used, stored on your contact so we know which places reach hosts; this uses no cookies. Every email has an unsubscribe link. We never sell or share your address.</p><h2>Feedback</h2><p>Feedback you send through the "Did this answer your question?" box comes to us by email with the page address. Your email address is optional.</p><h2>Embedded widgets</h2><p>The embeddable checker and levy calculator do not load analytics or set cookies.</p><h2>Contact</h2><p>Questions or requests about your data: <a href="mailto:hello@ukshortletrules.co.uk">hello@ukshortletrules.co.uk</a>.</p><p>The UK Short-Let Rules team</p>',desc='What the UK Short-Let Rules Tracker collects: optional Google Analytics 4 with consent, cookieless Cloudflare Web Analytics, and newsletter emails via Resend.')
