CX.update({
'bridgend':dict(lic=WA_REG,ctrl=WPL25(),levy=WLV,
 fees=('WRA registration is free. Council tax second-home premium: 200% on top of the standard charge (so a bill of 300%, triple the normal amount) from 1 Apr 2026. Council decided on 20 Sep 2023 to start a 100% premium on second homes from 1 Apr 2024 and raise it to 200% after two years, which makes Bridgend one of the highest-charging councils in Wales. It applies to substantially furnished homes that are not anyone\'s sole or main home. Long-term empty homes (empty and unfurnished for a year) have paid a premium since 1 Apr 2023, also rising after two years. Exceptions: Class 1 and 2 (marketed for sale or let, one year only), Class 3 (annexes), Class 4 (armed forces), Class 5 (occupied caravan pitches and boat moorings), Class 6 (a planning condition prevents year-round or main-residence use, or limits the home to holiday letting) and Class 7 (job-related homes). Claim an exception by emailing premiums@bridgend.gov.uk. The council collected about £161,000 from the second-home premium in 2025/26. A 2022 planning report found no obvious local concentration of second homes or short-term lets, but noted the Porthcawl Waterfront redevelopment could justify limits later.',[BGD,BGD2,BGD3]),
 dates=['1 Apr 2024: 100% second-home premium started','1 Apr 2026: second-home premium rises to 200% (300% bill)','31 Mar 2027: WRA registration deadline']),
'newport':dict(lic=WA_REG,ctrl=WPL25(),levy=WLV,
 fees=('WRA registration is free. Council tax second-home premium: 100% on top of the standard charge (so double) since 1 Apr 2025, still charged in 2026/27. The council says this can include short-term holiday lets that pay council tax rather than business rates. Long-term empty homes (empty and unfurnished for a year or more) have paid a 100% premium since 1 Apr 2024, and Newport gives no discount on empty unfurnished homes. Exceptions: Class 1 (marketed for sale, one year only), Class 2 (marketed for a let of at least 6 months, one year only; holiday lets and Airbnb short lets do not count), Class 3 (annexes), Class 4 (armed forces), Class 5 (occupied caravan pitches and boat moorings), Class 6 (a planning condition restricts occupancy for at least 28 days a year, limits the home to holiday letting, or prevents main-residence use) and Class 7 (job-related homes provided by an employer). Your bill shows if the premium applies.',[NWP,NWP2]),
 dates=['1 Apr 2024: long-term empty premium started','1 Apr 2025: 100% second-home premium started','31 Mar 2027: WRA registration deadline']),
})
