CX.update({
'neath-port-talbot':dict(lic=WA_REG,ctrl=WPL25(),levy=WLV,
 fees=('WRA registration is free. Council tax second-home premium: 100% on top of the standard charge (so double) since 1 Apr 2025, still charged in 2026/27 (2026/27 tax base report). Long-term empty homes (empty and unfurnished for a year) pay the same 100% premium. Holiday-let owners should know about local exception D, added from 1 Apr 2026: if a self-catering property is moved off the business rates list onto council tax because it no longer meets the letting criteria, the council can waive the premium for 6 months from the date it was moved, giving time to appeal to the Valuation Office or decide what to do with the property (the move is usually backdated, which otherwise means a large backdated premium). Apply by calling the Council Tax Team on 01639 686188, option 2. Local exception C gives 6 months without the premium when a home is left empty after a parent or step-parent dies. National exceptions: Class 1 and 2 (marketed for sale, or for a let of at least 6 months, one year only; holiday lets and Airbnb short lets do not count), Class 3 (annexes), Class 4 (armed forces), Class 5 (occupied caravan pitches and boat moorings), Class 6 (a planning condition restricts occupancy for at least 28 days a year, limits the home to holiday letting, or prevents main-residence use) and Class 7 (job-related homes).',[NPT,NPT2,NPT3]),
 dates=['20 Mar 2024: Council approves premiums on second homes and long-term empty homes','1 Apr 2025: 100% second-home premium started','1 Apr 2026: 6-month exception for self-catering lets moved from business rates','31 Mar 2027: WRA registration deadline']),
'rhondda-cynon-taf':dict(lic=WA_REG,ctrl=(_rctpl[0],_rctpl[1]+[RCT3]),levy=WLV,
 fees=('WRA registration is free. Council tax second-home premium: 100% on top of the standard charge (so double) since 1 Apr 2024, agreed by the council in January 2023 and still shown in the council\'s current council tax guide. It applies to homes that are not anyone\'s sole or main residence and are substantially furnished. Long-term empty homes (empty and unfurnished for a year) have paid a premium since 1 Apr 2023: from 1 Apr 2025 that is 100% after 1 to 3 years and 200% after more than 3 years. Exceptions: Class 1 and 2 (marketed for sale, or for a let of at least 6 months, one year only), Class 3 (annexes), Class 4 (armed forces), Class 5 (occupied caravan pitches and boat moorings), Class 6 (a planning condition prevents year-round or main-residence use, or limits the home to holiday letting) and Class 7 (job-related homes). Apply for an exception through the council\'s premiums page. The council says the number of second homes paying the premium rose from 491 on 1 Apr 2023 to 647 by 31 Mar 2024.',[RCT,RCT2]),
 dates=['Jan 2023: Council agrees council tax premiums','1 Apr 2023: long-term empty premium started','1 Apr 2024: 100% second-home premium started','1 Apr 2025: long-term empty premium rises (200% after 3 years)','31 Mar 2027: WRA registration deadline']),
})
