_cpl=WPL25()
CX.update({
'caerphilly':dict(lic=WA_REG,ctrl=('No Article 4 direction or local short-let planning control on second homes or short-term lets found (checked 25 Oct 2026). The council\'s three Article 4 directions (Bute Town and Rhymney Town in Rhymney, and Pontywaun Garden Suburbs in Crosskeys) protect the look of conservation areas, such as windows, roofs and front walls, and do not cover changes of use. Wales-wide, use classes C3 (main home), C5 (second home) and C6 (short-term let) exist since Oct 2022, and moving between them is permitted development unless an Article 4 direction applies.',_cpl[1]+[CAEA4]),levy=WLV,
 fees=('WRA registration is free. Council tax second-home premium: 100% on top of the standard charge (so double) since 1 Apr 2025, agreed by Cabinet on 20 Mar 2024 and full Council on 27 Mar 2024, and still charged in 2026/27 (the council\'s 2026/27 return to the Welsh Government shows 175 second homes paying the 100% premium). It applies to homes that are not anyone\'s sole or main residence and are substantially furnished. Long-term empty homes (empty and unfurnished) pay nothing extra until they have been empty for 2 years: then 100%, rising to 200% after 3 years and 300% after 5 years. Exceptions: Class 1 and 2 (marketed for sale or let, one year only), Class 3 (annexes), Class 4 (armed forces), Class 5 (occupied caravan pitches and boat moorings), Class 6 (seasonal homes where year-round occupation is prohibited) and Class 7 (job-related homes). The council lists no local exception for holiday lets moving from business rates to council tax (checked 25 Oct 2026). To claim an exception, email premiums@caerphilly.gov.uk with evidence, such as an estate agent\'s agreement and listing link, or a planning reference number for annexes or homes with planning restrictions.',[CAE,CAE2,WCT1]),
 dates=['27 Mar 2024: Council approves premiums on second homes and long-term empty homes','1 Apr 2025: 100% second-home premium started','31 Mar 2027: WRA registration deadline']),
'torfaen':dict(lic=WA_REG,ctrl=WPL25(),levy=WLV,
 fees=('WRA registration is free. No council tax second-home premium: Torfaen is one of only two Welsh councils not charging one in 2026/27 (Welsh Government council tax dwellings return: 0 homes on any premium in Torfaen), and it does not charge a long-term empty premium either. The council says it is considering premiums on second homes and long-term empty homes, is reviewing how many properties would be affected, and that any decision would need public consultation and councillors\' approval. Its stated approach for now is to help owners bring empty homes back into use rather than charge a premium. A council\'s first decision to charge a second-home premium must be made at least a year before the financial year it starts, so check the council\'s page before buying. Second homes and empty homes get no council tax discount, so a furnished holiday let on council tax pays the standard bill (2026/27 bill notes).',[TOR,TOR3,WCT1,TOR2]),
 dates=['1 Apr 2026: still no second-home premium (2026/27 return)','31 Mar 2027: WRA registration deadline']),
})
# ---- Blaenau Gwent, Merthyr Tydfil (sources read 25 Oct 2026) ----
BGW='https://blaenau-gwent.gov.uk/en/resident/council-tax/council-tax-premium-for-long-term-empty-property'
