CX.update({
'blaenau-gwent':dict(lic=WA_REG,ctrl=WPL25(),levy=WLV,
 fees=('WRA registration is free. Council tax second-home premium: UNVERIFIED for 2026/27, because the sources disagree. The council\'s premiums page says a 100% second-home premium (so a double bill) starts on 1 Apr 2026 for homes that are nobody\'s sole or main residence and are substantially furnished. But the council\'s own 2026/27 return to the Welsh Government shows no second homes paying a premium, and GOV.WALES says only 20 of the 22 Welsh councils charge one in 2026/27. Ask the council (Premiums@blaenau-gwent.gov.uk, 01495 363900) which applies before you budget. Long-term empty homes (empty and unfurnished for over 12 months) have paid a premium since 1 Apr 2025: 100% after 1 to 2 years, 200% after 2 to 3 years and 300% after more than 3 years, ignoring any time empty before 1 Apr 2024. Exceptions: Class 1 and 2 (marketed for sale or let, one year only), Class 3 (annexes), Class 4 (armed forces), Class 5 (occupied caravan pitches and boat moorings), Class 6 (seasonal homes or holiday lets where year-round occupation is prohibited) and Class 7 (job-related homes), plus local exceptions for long-term empty homes only (new buyers for up to 12 months, awaiting an empty-property grant or loan, complex legal issues, awaiting planning permission, and some mixed-use buildings). Apply with the council\'s premium exception form.',[BGW,WCT1]),
 dates=['1 Apr 2025: long-term empty premium started','1 Apr 2026: 100% second-home premium due to start per the council page (UNVERIFIED: 2026/27 return shows none)','31 Mar 2027: WRA registration deadline']),
'merthyr-tydfil':dict(lic=WA_REG,ctrl=WPL25(),levy=WLV,
 fees=('WRA registration is free. Council tax second-home premium: 100% on top of the standard charge (so double) since 1 Apr 2024, kept for 2025/26 (full Council, 6 Nov 2024) and for 2026/27 (full Council, 11 Feb 2026, as reported by Nation.Cymru). The council\'s 2026/27 return to the Welsh Government shows 171 second homes paying the 100% premium. It applies to homes that are substantially furnished and are not the owner\'s or occupier\'s sole or main residence. Long-term empty homes: exempt for the first 6 months after becoming unfurnished, then the full charge, then a premium once empty for over a year: 100% (1 to 5 years), 150% (5 to 10 years) and 200% (over 10 years). Exceptions: Classes 1 to 7 (marketed for sale or let, one year only; annexes; armed forces; occupied caravan pitches and boat moorings; a planning condition stops year-round occupation or limits the home to holiday use; job-related homes), plus local Class 8 (new owners bringing a property back into use, and mixed-use buildings) and, from 1 Apr 2025, Class 9 (ongoing renovation, up to 6 months). Contact revenues@merthyr.gov.uk or 01685 725000. Band D for 2026/27 is £2,591.47 (£2,625.36 in Trelewis and Bedlinog).',[MTP,MTP2,WCT1,MTP3]),
 dates=['1 Apr 2024: 100% second-home premium started','11 Feb 2026: Council keeps 100% second-home premium for 2026/27','31 Mar 2027: WRA registration deadline']),
})
# ---- Falkirk and the island councils (sources fetched 24 Oct 2026) ----
VSE='https://www.visitscotland.org/tourism-events-industry/visitor-levy'
CX.update({
'falkirk':dict(lic=(SC_LIC[0]+' Falkirk Council takes applications using its <a href="https://www.falkirk.gov.uk/businesses-premises-venues-licenses/short-term-lets" rel="nofollow">short-term let application pack</a> (Licensing Board: licensing@falkirk.gov.uk, 01324 501575). The council publishes a public register of short-term let licences.',SC_LIC[1]+['https://www.falkirk.gov.uk/businesses-premises-venues-licenses/short-term-lets']),
 ctrl=(NOCA[0]+' Check whether your let needs planning permission anyway; Falkirk links to a separate short-term lets planning page from its licensing page.',NOCA[1]+['https://www.falkirk.gov.uk/businesses-premises-venues-licenses/short-term-lets']),
 levy=('Not approved. Formal consultation on a draft scheme runs from 2 Sep to 25 Nov 2026: 5% of the cost of overnight accommodation only (not food, parking or other extras), with providers proposed to keep 2%. The council says it has not decided, and full Council is expected to consider it in January 2027 (the consultation page says early 2027). Any Scottish levy needs at least 18 months\' notice before it starts.',['https://www.falkirk.gov.uk/visitor-levy/the-levy','https://fcwebsites.blob.core.windows.net/www/media/e2c569be-f9a8-4fb3-8090-b97aae41bafd/Frequently-Asked-Questions-FAQs-Falkirk-Council-Draft-Visitor-Levy-Scheme.pdf',VSE]),
 fees=('From the council\'s published 2025/26 fee table (the latest short-term let table we found; check for a 2026/27 update). The same fee applies to new, renewal and temporary applications. Secondary letting: £315 (up to 4 guests) / £504 (5 or more). Home letting, home sharing, or both: £157.50 / £315. Paid as 20% at provisional grant and 80% at confirmation. Transfer £105.',['https://www.falkirk.gov.uk/licensing-fees-and-charges/licensing-fees-and-charges/short-term-lets-licensing-scheme']),
 dates=['2 Sep 2026: levy consultation opened','25 Nov 2026: levy consultation closes','Jan 2027: full Council expected to decide on a levy']),
'orkney-islands':dict(lic=(SC_LIC[0]+' <a href="https://www.orkney.gov.uk/business-and-licensing/licensing-information-and-applications/short-term-lets-licensing" rel="nofollow">Apply through Orkney Islands Council</a>: guidance notes, application form, floor and location plans, and a separate Scottish Fire and Rescue Service fire safety checklist. You display a notice at the property (28-day objection period) only when the council asks you to. The council publishes a register of licences.',SC_LIC[1]+['https://www.orkney.gov.uk/business-and-licensing/licensing-information-and-applications/short-term-lets-licensing']),
 ctrl=NOCA,
 levy=('No levy. The council\'s Policy and Resources Committee decided on 23 Sep 2025 not to go ahead with an overnight visitor levy "at this time", after a feasibility study with Shetland and the Western Isles found strong local opposition, practical problems and marginal returns. The council prefers a cruise ship or point-of-entry levy, which the current law does not allow.',['https://www.orkney.gov.uk/latest-news/orkney-islands-council-decides-against-overnight-visitor-levy']),
 fees=('3-year licence, 2026/27 fees (3.8% up on 2025/26). Secondary letting: £354 (up to 4 guests), £434 (5 to 9), £583 (10 or more). Home sharing and home letting: £275 / £343 / £457. Non-linked isles get 25% off: secondary £266 / £326 / £437, home sharing and letting £206 / £257 / £343. Temporary licence (up to 6 weeks) £275 (£206 non-linked isles), transfer £138 (£103). The first £275 of each application fee is non-refundable.',['https://www.orkney.gov.uk/business-and-licensing/licensing-information-and-applications/short-term-lets-licensing']),
 dates=['23 Sep 2025: council decides against an overnight visitor levy','1 Apr 2026: 2026/27 licence fees (3.8% increase)']),
'shetland-islands':dict(lic=(SC_LIC[0]+' Shetland Islands Council\'s Environmental Health team runs the scheme: apply through the council\'s online portal, by email to stl@shetland.gov.uk, or by post to Environmental Health, Gutters\' Hut, 7 North Ness, Lerwick ZE1 0LZ. Fees are non-refundable whether or not a licence is granted.',SC_LIC[1]+['https://www.shetland.gov.uk/stl','https://www.shetland.gov.uk/downloads/file/6364/short-term-lets-licensing-policy']),
 ctrl=NOCA,
 levy=('No levy. Councillors on the Policy and Resources Committee decided against an overnight visitor levy in September 2025 after a feasibility study said the risks outweighed the benefits. The council has been looking at a point-of-entry levy instead, which would need new law.',['https://www.bbc.com/news/articles/cj6xrkd3l9ro','https://www.orkney.gov.uk/latest-news/orkney-islands-council-decides-against-overnight-visitor-levy']),
 fees=('2026/27 fees, now set by guest numbers rather than bedrooms. Home sharing or home letting: £210 (1 to 6 guests) / £335 (7 or more). Secondary letting: £370 / £530. Admin fee £37. From the council\'s 2026-27 Environmental Health charges schedule (shetland.gov.uk blocked our direct check, so read via a search index of the official file on 24 Oct 2026).',['https://www.shetland.gov.uk/downloads/file/7747/environmental-health-charges']),
 dates=['Sep 2025: council decides against an overnight visitor levy','1 Apr 2026: 2026/27 licence fees']),
'na-h-eileanan-siar':dict(lic=(SC_LIC[0]+' <a href="https://www.cne-siar.gov.uk/stl" rel="nofollow">Comhairle nan Eilean Siar short-term lets pages</a>: send the completed application and fee to stl@cne-siar.gov.uk, any Comhairle office, or by post to Stornoway. Submit renewals, with everything needed, about 3 months before your licence expires; if a complete renewal is not in before expiry you count as a new operator and cannot take bookings or guests until licensed.',SC_LIC[1]+['https://www.cne-siar.gov.uk/stl']),
 ctrl=NOCA,
 levy=('No levy. The Comhairle has paused detailed work on an accommodation-based visitor levy, citing challenges for island businesses, and is looking at other options for funding tourism. It says any formal proposal would be consulted on before councillors consider it.',['https://www.cne-siar.gov.uk/business/tourism/outer-hebrides-visitor-levy/latest-information','https://www.cne-siar.gov.uk/business/tourism/outer-hebrides-visitor-levy/latest-information/next-steps-and-further-engagement']),
 fees=('3-year licence, 2026/27 fees: a base fee plus £21 per guest. First application: home sharing £189, secondary letting, home letting, or both home sharing and letting £294. Renewal: home sharing £84, the others £189. Example: a 6-guest secondary let costs £294 + 6 × £21 = £420. Temporary exemption (up to 6 weeks) £53, transfer £53, variation £53. No refunds once an application is processed.',['https://www.cne-siar.gov.uk/stl/fees-and-how-pay','https://www.cne-siar.gov.uk/business/fees-and-charges/fees-and-charges-licensing-and-miscellaneous/short-term-lets']),
 dates=['1 Apr 2026: 2026/27 licence fees']),
})
# ---- South Ayrshire and Angus (sources fetched 24 Oct 2026) ----
SAY='https://www.south-ayrshire.gov.uk/article/40559/Short-Term-Let-Licensing-Scheme-South-Ayrshire'
SAYP='https://www.south-ayrshire.gov.uk/media/6936/South-Ayrshire-Council-Short-Term-Let-Licensing-Scheme/pdf/Short_Term_Let_Policy_revised_August_24.pdf?m=1725447111317'
ANG='https://www.angus.gov.uk/licences_and_permits/short_term_lets'
CX.update({
'south-ayrshire':dict(lic=(SC_LIC[0]+' <a href="'+SAY+'" rel="nofollow">Apply online through South Ayrshire Council</a> and pay at the end. Send everything on the council\'s checklist with the application (incomplete ones are rejected and the fee is not refunded): a scaled floor plan, a video of the property, the Scottish Fire and Rescue checklist, a legionella risk assessment and a planning operational statement. You then display a site notice at or near the property for 21 days from the date you applied and send a certificate of compliance. Renewals must go in before your licence expires.',SC_LIC[1]+[SAY,SAYP]),
 ctrl=(NOCA[0]+' South Ayrshire asks every applicant for a planning operational statement, so its planning team can decide during the consultation whether your let needs planning permission.',NOCA[1]+[SAY]),
 levy=('No levy. A report to the council\'s Cabinet on 17 June 2025 recommended pausing all work on a visitor levy until August 2027, after a survey in which 79% of 502 responses opposed one. Even if it is revived then, the council would need to publish a scheme, consult on it and give at least 18 months\' notice before charging. (We have seen the report\'s recommendation but not a record of the Cabinet vote, so treat the pause as reported, not confirmed.)',['https://www.south-ayrshire.gov.uk/article/80918/Future-of-proposed-Visitor-Levy-in-South-Ayrshire','https://www.south-ayrshire.gov.uk/media/15276/Visitor-Levy-Scheme/pdf/item_9a_20250617_C_Visitor_Levy_beyeswk2q9ik.pdf?m=1749210282673']),
 fees=('New licence: secondary letting £300 (up to 4 guests) / £480 (5 or more); home sharing or home letting (or both) £150 / £300. Renewal: secondary £240 / £420; home sharing or letting £90 / £240. Temporary licence £120, variation £90, replacement licence £60. Fees are non-refundable. These are the fees in the council\'s August 2024 policy and on its scheme page. The council consulted on a revised policy, including an updated fee structure, until 12 June 2026, so check for new fees before you apply. (south-ayrshire.gov.uk blocked our direct check; read via a search index of the official pages on 24 Oct 2026.)',[SAY,SAYP]),
 dates=['17 Jun 2025: Cabinet report recommends pausing levy work','12 Jun 2026: licensing policy and fee review consultation closed','Aug 2027: earliest the levy would be looked at again']),
'angus':dict(lic=(SC_LIC[0]+' Apply through <a href="'+ANG+'" rel="nofollow">Angus Council\'s short-term lets pages</a>. A new licence lasts up to 3 years and a renewal up to 6 years. If you started letting after 1 Oct 2022 you cannot trade until licensed, and the council has 9 months to decide. A temporary licence lasts up to 6 weeks, and you can get up to three temporary exemptions totalling no more than 6 weeks in 12 months. The council keeps a public register of short-term lets.',SC_LIC[1]+[ANG+'?page_id=1844',ANG+'?page_id=1845']),
 ctrl=(NOCA[0]+' Angus Council confirms there are currently no short-term let control areas in Angus, and says that could change.',NOCA[1]+[ANG+'?page_id=1851']),
 levy=('No levy. In June 2024 the Policy and Resources Committee said it was not making any decision to introduce a levy and asked officers to engage with stakeholders first. In October 2025 the council set aside £50,000 of UK Shared Prosperity funding for a tourism framework and early engagement on a possible levy. There is no published scheme or consultation yet, and any Scottish levy needs at least 18 months\' notice.',['https://www.angus.gov.uk/sites/default/files/2024-05/Report%20170_24%20Consideration%20of%20the%20Introduction%20of%20a%20Local%20Visitor%20Levy.pdf','https://www.angus.gov.uk/sites/default/files/2025-09/Report%20289_25_UK%20Shared%20Prosperity%20Fund%202025-26%20Funding%20Update%20and%20Allocations.pdf']),
 fees=('Same fee for all licence types, set by guest numbers: £349 (1 to 5 guests), £460 (6 to 20), £588 (more than 20) for a new 3-year licence or a 6-year renewal. Provisional licence 20% of the full fee (£69.80 / £92 / £117.60), confirmation 80% (£279.20 / £368 / £470.40). Temporary licence or temporary exemption £174.50, variation £75, transfer £75, duplicate £20. No refund if refused or granted for a shorter period. The April 2026 licensing fee rise did not cover short-term lets, so these still apply.',[ANG+'?page_id=1846','https://www.angus.gov.uk/sites/default/files/2026-03/Report%20107_26%20Review%20of%20Fees.pdf']),
 dates=['4 Jun 2024: committee asks for stakeholder engagement on a levy (no decision)','14 Nov 2024: updated licensing policy considered','Oct 2025: £50,000 set aside for early levy engagement']),
})
# ---- North Ayrshire (sources fetched 24 Oct 2026) ----
NAY='https://www.north-ayrshire.gov.uk/business-licensing/licensing/accommodation-licences'
NAYP='https://www.north-ayrshire.gov.uk/documents/short-term-let-licensing-policy'
CX.update({
'north-ayrshire':dict(lic=(SC_LIC[0]+' Apply to <a href="'+NAY+'" rel="nofollow">North Ayrshire Council\'s licensing team</a>, using its STL licensing checklist to gather your supporting documents, and include the fee. A licence lasts 3 years from the date of issue and is normally renewed for a further 3 years. If you apply to renew before it expires, your licence carries on until the council decides. Processing can take up to 3 months. Where public notification is needed, a site notice is normally displayed for 21 days. This covers the mainland and the islands of Arran and Cumbrae.',SC_LIC[1]+[NAY,NAYP]),
 ctrl=(NOCA[0]+' North Ayrshire\'s licensing policy confirms the council does not currently have a short-term let control area and has not adopted an overprovision approach. You may still need planning permission, depending on the property.',NOCA[1]+[NAYP]),
 levy=('No levy yet. North Ayrshire\'s 2025 Visitor Management Plan says officers are looking at a possible visitor levy, including stakeholder pre-consultation and an options appraisal, with a report to Cabinet to follow. In January 2026 the Scottish Government said the council had not yet confirmed whether it will go ahead. There is no published scheme, and any Scottish levy needs at least 18 months\' notice. Separately, second homes in North Ayrshire (including on Arran and Cumbrae) have paid a 100% council tax premium (double council tax) since 1 April 2025; a let that qualifies for business rates is not charged council tax.',['https://north-ayrshire.cmis.uk.com/north-ayrshire/Document.ashx?czJKcaeAi5tUFL1DTL2UE4zNRBcoShgo=yjfa8npxsHO7tKbtvX6Ji80pJxePKDYY%2BU9pxstDRxUOF0P%2Bxu8%2BiQ%3D%3D','https://www.gov.scot/publications/visitor-levy-amendment-scotland-bill-island-communities-impact-assessment-icia/','https://www.north-ayrshire.gov.uk/Document-library/strategic-housing-investment-plan.pdf']),
 fees=('Fees from 1 April 2026, by maximum occupancy (up to 4 guests / 5 or more). New licence: secondary let £300 / £480; home sharing or home letting (or both) £150 / £300. Renewal: secondary let £240 / £420; home sharing or letting £135 / £240. Provisional licence: 25% of the new fee when you apply, 75% on confirmation. Temporary licence: 50% of the new fee. Amendment £75, variation £90, transfer £110, replacement licence £60. No refund if refused, withdrawn or granted for a shorter period.',[NAY]),
 dates=['12 Feb 2025: council approves 100% second homes council tax premium','1 Apr 2025: second homes premium starts','1 Apr 2026: current licence fees apply','Jan 2026: Scottish Government says levy decision not yet confirmed']),
})
