CX.update({
'midlothian':dict(lic=(SC_LIC[0]+' Midlothian Council asks you to <a href="'+MID+'" rel="nofollow">pay online first</a>; the payment receipt number and time then go on the main application form. Questions go to shorttermlet@midlothian.gov.uk. The council links its Short-term Lets Policy (2022), a fire safety checklist and a Legionnaires\' disease risk assessment, and publishes a public licence register. Renew before your licence expires: if you do, you can keep operating until the old licence ends or the council decides, whichever is later. A late renewal is treated as a new application and you must stop taking bookings until it is granted; the council may accept one made within 28 days of expiry on good grounds, case by case. Operating without a licence can mean a fine of up to £2,500 and a one-year ban from applying.',SC_LIC[1]+[MID,MIDP]),
 ctrl=(NOCA[0]+' You may still need planning permission depending on the property, and secondary lets must show their planning status when applying.',NOCA[1]),
 levy=('No levy. Midlothian ran a visitor levy survey in 2024 (24 responses), which the council called inconclusive. Officers are monitoring Edinburgh, Argyll and Bute and Aberdeen and said Midlothian would reassess a levy in 2026; we found no 2026 decision yet (searched 24 Oct 2026). A 2023 council report estimated a levy might raise about £180k a year against running costs of £190k to £500k. Any Scottish levy needs at least 18 months\' notice.',[MIDL,'https://www.edinburghnews.scotsman.com/news/politics/council/tourist-tax-midlothian-wont-follow-edinburgh-lead-as-report-warns-visitor-levy-may-cost-more-than-it-raises-4423759']),
 fees=('Fees from 1 April 2026, the same for a new licence or a renewal. Secondary letting: up to 4 bedrooms / 8 guests £541; 5 to 8 bedrooms / 16 guests £609; 8 to 12 bedrooms / 16 to 24 guests £767; above that £61 per extra room or guest. Home sharing or home letting: 1 bedroom / 3 guests £247; 2 to 3 bedrooms / 9 guests £290; 4 bedrooms / 9 guests £383; above that £61 per extra room or guest. A material change or licence transfer costs £315 / £368 / £452 (secondary) or £116 / £152 / £221 (home), and a variation £89. Duplicate licence £37; a visit made necessary by the host\'s failure £127 an hour.',[MID]),
 dates=['1 Oct 2022: licensing scheme opens','1 Apr 2026: current fees apply','2026: council to reassess a visitor levy']),
'west-lothian':dict(lic=(SC_LIC[0]+' <a href="'+WLO+'" rel="nofollow">Apply online through West Lothian Council</a>, then email your evidence to stl@westlothian.gov.uk. The council will not hold an incomplete application. Its list of required documents includes planning permission or a certificate of lawfulness (for every application, see below), a 1:50 floor plan showing room sizes, fire escapes, alarms and fire doors (not needed for an unchanged renewal), owner consent where you are not the owner, an EPC where one applies, a fire safety risk assessment, a gas safety certificate (where there is gas), an EICR and a PAT report. The council checks with Scottish Fire and Rescue, which may lead to an inspection.',SC_LIC[1]+[WLO,WLOP]),
 ctrl=('No control area. mygov.scot lists only two in Scotland (all of Edinburgh, and Badenoch &amp; Strathspey in Highland). But West Lothian says every short-term let licence application, of any type, must come with planning permission or a certificate of lawfulness for short-stay use (or one confirming the use is not a material change), and an application without one cannot be progressed. Contact the planning service directly, as the licensing team cannot advise on planning.',[MG_CA,WLO]),
 levy=('No levy yet. In June 2025 the Council Executive agreed to start early engagement with tourism businesses on a possible levy (a report modelled 2% and 5% rates), and the council stressed no decision had been made. We found no formal consultation or scheme since (searched 24 Oct 2026). Any Scottish levy needs at least 18 months\' notice.',[WLOL,'https://theedinburghreporter.co.uk/2025/06/tourist-tax-could-generate-1m-income-in-west-lothian/']),
 fees=('<span class="tag warn">check with council</span> West Lothian publishes two different fee tables. The council\'s Schedule of Fees and Charges 2025/26 sets fees by bedrooms: secondary letting £500.86 (1 bedroom), £612.16 (2 to 3), £801.38 (4 to 6), £1,113.03 (7 or more); home sharing or letting £361.73, £467.47, £662.25, £962.77. Variation £166.95, temporary licence 50% of the full fee, temporary exemption £333.91, inspection and report £133.56. The short-term lets web page still shows the fees agreed in December 2022, set by guests: secondary letting £450 (1 to 2 guests), £550 (3 to 6), £720 (7 to 12), £1,000 (12 to 14); home sharing or letting £325, £420, £595, £865; variation £50, transfer £120. We have not found a 2026/27 schedule, so confirm the current fee with stl@westlothian.gov.uk before you pay. The council says there are no discounts for multiple properties.',[WLOF,WLO]),
 dates=['20 Dec 2022: original fees agreed','Jun 2025: council agrees early engagement on a visitor levy','Oct 2025: updated Short Term Let Policy published']),
})
