CX.update({
'inverclyde':dict(lic=(SC_LIC[0]+' Inverclyde Council has no online form: complete the application form and checklist from its <a href="'+INV+'" rel="nofollow">short-term lets policy page</a>, plus the Scottish Fire and Rescue and Police Scotland checklists, and email them with copies of your documents to licensing.section@inverclyde.gov.uk (or post them to the Licensing Section, Municipal Buildings, Greenock). The same form is used for a new licence, a renewal or a variation. Pay the fee by card over the phone or by bank transfer, quoting the let\'s address. Display a site notice at or near the property for 21 days from the day you apply, then send the council a certificate of compliance with a copy of the notice. Police Scotland and Scottish Fire and Rescue are consulted. Licences and renewals are normally granted for three years, and the council has 9 months to decide a complete application.',SC_LIC[1]+[INV,INVA]),
 ctrl=(NOCA[0]+' But Inverclyde asks you to contact its planning service (dmplanning@inverclyde.gov.uk) before you apply, to confirm whether you need planning permission or a certificate of lawful use. Where planning permission is needed and has not been obtained, the council can reject the licence application within 14 days ("preliminary refusal") with no refund.',NOCA[1]+[INV,INVA]),
 levy=('No levy. In June 2026 the Policy and Resources Committee agreed to monitor the national rollout of visitor levies before making any decision for Inverclyde. A council report estimated up to 178 chargeable rooms, with a 2.5% levy raising about £300k a year, which set-up and running costs could cancel out; informal engagement found most local businesses against a levy. The council is more interested in a possible cruise ship levy, which would need new law. Any Scottish levy needs at least 18 months\' notice.',[INVL]),
 fees=('Fees from 1 April 2026, by maximum occupancy (4 or under / 5 or more). New licence: secondary letting £508 / £621; home letting or home sharing (or both) £311 / £396. Renewal: secondary letting £451 / £564; home letting or sharing £254 / £339. Variation £85 for any type. These figures are in the council\'s 2026 short-term lets fee list and its 2026/27 fees and charges booklet. Its short-term lets policy web page still shows the older table (secondary £450 / £550 new, £400 / £500 renewal; variation £75), so if in doubt confirm with licensing.section@inverclyde.gov.uk before you pay.',[INVF,INVB,INV]),
 dates=['1 Oct 2022: licensing scheme opens','28 Nov 2024: licensing policy last reviewed','1 Apr 2026: current fees apply','Jun 2026: council agrees to monitor levies before deciding']),
'renfrewshire':dict(lic=(SC_LIC[0]+' <a href="'+REN+'" rel="nofollow">Apply and pay online through Renfrewshire Council\'s MyAccount</a> (electronic signatures accepted). A new application needs a plan of the accommodation (not to scale, showing what the policy requires), buildings insurance and public liability insurance, plus proof of right to work and a criminal record check; a provisional licence is also available. Display the council\'s notice at or near the premises for 21 days from the day you apply (objections close 28 days after you apply), then return the notice and a signed certificate of compliance. Police Scotland, Scottish Fire and Rescue, the local councillor, the community council and the council\'s planning team are consulted. If there is an objection, the Regulatory Functions Board decides and you can appeal to the Sheriff within 28 days. The council aims to consider applications within 3 months and decide within 9. A licence lasts three years; apply to renew at least 6 weeks before it expires, or it stops being valid. To change licence type you need a new application, not a variation. Questions go to licensing.cs@renfrewshire.gov.uk.',SC_LIC[1]+[REN]),
 ctrl=(NOCA[0]+' You may still need planning permission depending on the property; Renfrewshire\'s planning team checks every application for relevant planning consents.',NOCA[1]+[REN]),
 levy=('No levy yet. On 17 September 2025 the Leadership Board authorised officers to begin formal stakeholder consultation and develop a visitor levy proposition, after an estimate that a 5% levy could raise about £2m a year before costs. We found no published consultation or scheme since (searched 24 Oct 2026). Any Scottish levy needs at least 18 months\' notice.',[RENL]),
 fees=('Application fees from 1 April 2026, by bedrooms let (1 / 2 / 3 / 4 or more). Home letting, home sharing or both: £291 / £407 / £407 / £407. Secondary letting: £927 / £1,043 / £1,159 / £1,274. Provisional licence: home £189 / £264 / £264 / £264, secondary £603 / £678 / £754 / £829; confirming it then costs home £213 / £254 / £254 / £254, secondary £435 / £476 / £516 / £557. Temporary exemption £117, variation £117, material change of circumstances £117, transfer £89, certified duplicate or true copy £48, inspection after a complaint £156.87 an hour. Fees are not refunded if you are refused or withdraw. <span class="tag warn">check with council</span> The council does not publish a separate renewal fee, so confirm what you will pay to renew with licensing.cs@renfrewshire.gov.uk.',[REN]),
 dates=['1 Oct 2022: licensing scheme opens','17 Sep 2025: officers authorised to develop a visitor levy proposition','1 Apr 2026: current fees apply']),
})
