CX.update({
'north-lanarkshire':dict(lic=(SC_LIC[0]+' <a href="'+NLS+'" rel="nofollow">Download North Lanarkshire Council\'s application pack</a> (application form and guidance notes updated July 2026, site notice, certificate of compliance, mandatory conditions, the Scottish Fire and Rescue Service fire safety checklist and a legionella self-assessment form). Email the completed form and documents to PrivateSector@northlan.gov.uk, or post them to the Enterprise and Communities Built Environment Team (Short Term Lets), Station House, 950 Old Edinburgh Road, Bellshill ML4 3FG; call 01236 632 377 for a paper form or to pay electronically. You need a copy of your EPC (for a dwellinghouse) and floor plans, and the council returns incomplete applications. Each premises needs its own application. Every applicant gets a fit and proper person check with Police Scotland. Objections must be in writing within 28 days. Licences last 3 years; apply to renew before yours expires. The council publishes a register of licensed short-term lets (last updated 7 October 2026). Unlicensed lets are enforced by Police Scotland.',SC_LIC[1]+[NLS,NLG]),
 ctrl=(NOCA[0]+' North Lanarkshire says licensing and planning are separate: some properties may need planning permission for a change of use, decided by its Planning Service, so check with planning before you let.',NOCA[1]+[NLS]),
 levy=('No levy yet. A council working group is looking at whether a visitor levy is feasible, and consultants appointed in July 2026 are preparing a visitor strategy for 2027 to 2037 and a draft levy scheme for councillors to consider. A business survey closed on 28 September 2026. The council says a report will go to a future council meeting, which will decide whether to start public consultation. We found no consultation or decision (searched 25 Oct 2026). Any Scottish levy needs at least 18 months\' notice.',[NLH,NLT]),
 fees=('One fee for every licence type (secondary letting, home letting, home sharing, or both): £315 for up to 4 guests, £472.50 for 5 or more guests, for a 3-year licence. This is in the council\'s July 2026 guidance notes and on its short-term lets page (updated 7 October 2026). <span class="tag warn">check with council</span> The council does not publish a separate renewal fee, so confirm what you will pay to renew with PrivateSector@northlan.gov.uk.',[NLS,NLG]),
 dates=['1 Oct 2022: licensing scheme opens','Jul 2026: consultants appointed to draft a visitor levy scheme','Jul 2026: application form and guidance notes updated','28 Sep 2026: levy business survey closes','7 Oct 2026: licence register last updated']),
'east-dunbartonshire':dict(lic=(SC_LIC[0]+' Email the application form, the checklist and copies of all evidence to STL@eastdunbarton.gov.uk, or post them to the Homelessness and Prevention Team, Kirkintilloch Community Hub, 2-4 West High Street, Kirkintilloch G66 1AD (the form, template site notice and certificate of compliance are in the appendices of the council\'s <a href="'+EDP+'" rel="nofollow">short-term lets policy</a>; you can also ask for them on 0300 123 4510). Display the site notice at or near the property for 21 days from the day you apply, then send the certificate of compliance. Police Scotland and the Scottish Fire and Rescue Service are consulted and the council may visit; it may ask for a floor plan showing room sizes and escape routes. The council aims to decide within 21 days of the consultation period ending. Objections go to the Housing Appeals Board. Licences last up to 3 years, and a licence carries on while a renewal is decided. The council does not grant temporary exemptions or temporary licences. You can appeal a refusal within 28 days.',SC_LIC[1]+[EDP]),
 ctrl=(NOCA[0]+' Ordinary planning rules still apply: a short-term let can be a material change of use needing planning permission, so check with the council\'s planning service. If a licence is refused because you need planning permission, the council will not charge again for an application resubmitted within 28 days of planning permission being granted, provided you applied for planning without undue delay.',NOCA[1]+[EDP]),
 levy=('No levy. In summer 2026 councillors agreed unanimously, on the council leader\'s motion, not to bring in a visitor levy, before any formal consultation (reported 2 Jul 2026). A report had estimated a 5% levy could raise about £500,000 a year, or about £320,000 after running costs, and said local businesses who gave early feedback were opposed. Any future scheme would need consultation and at least 18 months\' notice.',[EDL]),
 fees=('One fee for a 3-year licence, the same for a new application or a renewal. Secondary letting £594 for up to 10 guests, plus £55 for every extra five guests (so £649 for 11 to 15). Home letting, or home letting and home sharing, £495 for up to 10 guests, plus £55 for every extra five. Home sharing £275 per room. Fees are not refunded if you are refused. The policy page does not say which year these fees apply from.',[EDP]),
 dates=['1 Oct 2022: licensing scheme opens','Jul 2026: council decides not to introduce a visitor levy']),
})
